FUNCTION_BLOCK FB_LoopCounter
VAR_INPUT
    i : BOOL;  // Trigger input for the counter
END_VAR
VAR
    macro : INT := 1;  // Current count
    micro : INT := 1;  // Control variable for counting down
END_VAR
VAR_OUTPUT
    o : INT;  // Current value of the counter
END_VAR

VAR
    tempMacro : INT;  // Temporary variable to hold macro value
    tempMicro : INT;  // Temporary variable to hold micro value
END_VAR

// Main logic
IF i THEN
    // Decrement micro
    micro := micro - 1;

    // Check if micro has reached zero
    IF micro <= 0 THEN
        // Increment macro
        macro := macro + 1;
        // Reset micro to the new value of macro
        micro := macro;
    END_IF
END_IF

// Ensure macro and micro do not go negative
IF macro < 1 THEN
    macro := 1;
END_IF

IF micro < 1 THEN
    micro := 1;
END_IF

// Set the output value
o := macro;

END_FUNCTION_BLOCK
